// tick-begin 子命令：一轮 tick 的开工三连——取锁（租约+代数）、序号入状态档、登记本会话派工。
// stdout 给出 {generation, tickSeq}；这一轮后续所有写类调用都必须带着这个代数（--gen）。
// 可选参数：--session 会话标识（记账归属靠它，见下方取值优先级）；--employee 登记成哪个员工
//          （默认「主控」）；--lease-ms 租约时长毫秒（默认 15 分钟）；--pid 持有者进程号
//          （默认本进程，带外的壳可传自己的常驻进程号，让探活盯对地方）。
//
// 会话标识取值优先级（E 项：会话标识机器盖章，tick-begin 不再只认自报值）：
//   ① SessionStart 钩子经 session-mark 盖的机器戳（runtime/current-session.json）——
//      真实、不可伪造，是记账归属的首选依据；
//   ② 没盖章（比如非 Claude Code 环境手工跑、钩子还没来得及跑）时退回显式 --session
//      （兼容旧写法，模型自报）；
//   ③ 两样都没有，退回「进程-<pid>」的兜底标识（老行为，非记账场景够用）。
// 机器戳和 --session 两样都有但对不上时，以机器戳为准，并在输出的 session_note 里注明——
// 不吞这个分歧，让带外调度器/审计能看见「模型报错了会话号」这件事本身。
async function cmdTickBegin({ root, flags }) {
  const reportedSession = typeof flags.session === 'string' && flags.session.trim() !== ''
    ? flags.session.trim()
    : null;
  const stamped = await readJson(root, RUNTIME_CURRENT_SESSION_PATH);
  const stampedSession =
    stamped !== null && typeof stamped.session_id === 'string' && stamped.session_id.trim() !== ''
      ? stamped.session_id.trim()
      : null;

  let session;
  let sessionNote;
  if (stampedSession !== null) {
    session = stampedSession;
    if (reportedSession !== null && reportedSession !== stampedSession) {
      sessionNote =
        `--session 报的「${reportedSession}」与机器盖章「${stampedSession}」不一致，` +
        '以机器盖章为准（SessionStart 钩子经 session-mark 登记的才是真实会话标识）';
    }
  } else {
    session = reportedSession ?? `进程-${process.pid}`;
  }

  const options = { session };
  if (flags['lease-ms'] !== undefined) {
    const leaseMs = Number(flags['lease-ms']);
    if (typeof flags['lease-ms'] !== 'string' || !Number.isInteger(leaseMs) || leaseMs <= 0) {
      throw new CliError('--lease-ms 需要带一个正整数（毫秒）');
    }
    options.leaseMs = leaseMs;
  }
  if (flags.pid !== undefined) {
    const pid = Number(flags.pid);
    if (typeof flags.pid !== 'string' || !Number.isInteger(pid) || pid <= 0) {
      throw new CliError('--pid 需要带一个正整数（进程号）');
    }
    options.pid = pid;
  }

  const got = await acquire(root, options);

