684	// acceptance-run 子命令：对某个里程碑执行可证伪验收（评判+结论入册+状态流转闭环）。
685	// 用法：acceptance-run <里程碑编号> --gen n（有锁在手时写类子命令必须报代数）
686	// 过/不过都算命令正常干完（退出码 OK），结论看 stdout 的 {pass, failed, incident}；
687	// 只有验收本身进行不下去（清单缺失、标准写坏等）才走错误退出码。
688	async function cmdAcceptanceRun({ root, positionals, flags }) {
689	  const id = positionals[0] ?? (typeof flags.id === 'string' ? flags.id : undefined);
690	  if (!id) {
691	    throw new CliError('acceptance-run 需要里程碑编号，例如：acceptance-run M1 --gen 3');
692	  }
693	  const actor = typeof flags.actor === 'string' && flags.actor.trim() !== '' ? flags.actor : '未署名';
694	  const result = await runAcceptance(root, id, { actor });
695	  return { output: { ok: true, milestone: id, ...result }, exit: EXIT.OK };
696	}
697	
698	// scaffold 子命令：建 .opc/ 的唯一命令行入口（后续 opc-init 命令和端到端演练都从这走）。
699	// 用法：scaffold --name <项目名> [--language <语言>]
700	// --language 现为可省（P10 T6：建项目不再收集语言，语言跟随用户由后续需求对话里底座
701	// 主动发现，宪法 14）——给了就必须非空文字，不给就把 undefined 原样递给 scaffoldProject，
702	// 由它落 meta.user_language = null。
703	// 已有 .opc/ 就白话报错退出；没有就从模板建出来（拷模板、回填 meta、登记指纹、记事件）。
704	async function cmdScaffold({ root, flags }) {
705	  if (typeof flags.name !== 'string' || flags.name.trim() === '') {
706	    throw new CliError('scaffold 需要 --name 带上项目名，例如：scaffold --name 我的项目');
707	  }
708	  let language;
709	  if (flags.language !== undefined) {
710	    if (typeof flags.language !== 'string' || flags.language.trim() === '') {
711	      throw new CliError('scaffold 的 --language 若给出必须带上非空文字，例如：scaffold --name 我的项目 --language 中文');
712	    }
713	    language = flags.language;
714	  }
715	  const result = await scaffoldProject(root, { name: flags.name, language });
716	  return { output: { ok: true, opc: result.created }, exit: EXIT.OK };
717	}
718	
719	// migrate 子命令：手动跑一次版本迁移链。
720	// 真正的迁移在分发前的版本预检里已经统一做过（宪法 13：任何入口先对版本），
721	// 这里只把那次预检的结果原样报出来，不再跑第二遍。
722	// 它本身不动 .opc/（动手的是预检，而预检对每个子命令一视同仁），所以不算写类子命令。
723	async function cmdMigrate({ migration }) {
724	  return { output: { ok: true, ...migration }, exit: EXIT.OK };
725	}
726	
727	// tokens-ingest 子命令：记账钩子的入口——解析一份会话记录、幂等入账。
728	// 用法：tokens-ingest --transcript <会话记录文件路径>
729	// 注意它不进写类围栏（WRITE_CLASS_COMMANDS）：它只往只增账本追加、更新入账进度档，
730	// 不碰状态机数据；而且是员工会话收尾时由钩子触发的，拿不到本轮代数——
731	// 记账不能因为锁在别人手里就丢账。
732	async function cmdTokensIngest({ root, flags }) {
733	  if (typeof flags.transcript !== 'string' || flags.transcript.trim() === '') {
734	    throw new CliError('tokens-ingest 需要 --transcript 带上会话记录文件的路径');
735	  }
736	  const result = await ingest(root, flags.transcript);
737	  return { output: { ok: true, ...result }, exit: EXIT.OK };
738	}
739	
740	// tokens-backfill 子命令：把一个项目历史上所有主会话记录重扫入账，补齐过去只记了主控、
741	// 漏掉的子代理（派工员工）用量。默认去 ~/.claude/projects/<项目路径转写>/ 找记录
742	// （路径里非字母数字的字符一律转成 -，对齐 Claude Code 的会话目录命名），
743	// 也可用 --transcripts-dir 显式指定。幂等：靠 message_id 去重，重复跑不会重复入账。
744	// 跟 tokens-ingest 一样不进写类围栏。
745	async function cmdTokensBackfill({ root, flags }) {
746	  const dir = typeof flags['transcripts-dir'] === 'string' && flags['transcripts-dir'].trim() !== ''
747	    ? flags['transcripts-dir']
748	    : path.join(os.homedir(), '.claude', 'projects', path.resolve(root).replace(/[^A-Za-z0-9]/g, '-'));
749	  const result = await backfill(root, dir);
750	  return { output: { ok: true, ...result }, exit: EXIT.OK };
751	}
752	
753	// ledger-unlatch 子命令：账修平后人工清掉断账控制位（state.ledger_gap），解冻 tick。
754	// 用法：ledger-unlatch。跟 tokens-ingest 一样不进写类围栏——它就是用来把断账态救回来的，
755	// 不能反被断账门（precheck 门⑧只在 tick 流里跑，这里也够不着它）挡住。
756	async function cmdLedgerUnlatch({ root }) {
757	  const result = await clearLedgerGap(root);
758	  return {
759	    output: { ok: true, ...result, message: result.wasSet ? '断账标志已清除，可以继续干活。' : '本来就没有断账标志，无需解除。' },
760	    exit: EXIT.OK
761	  };
762	}
763	
764	// approve / reject 子命令：批复的命令行入口。语义上就是「write approval-decision」那一笔，
765	// 多出来的确定性动作（盖 SG 签字编号、写回状态、记事件）归脚本，都在 lib/approvals.mjs 里。
766	// 用法：approve <请示编号> [--note 批注] [--via cli|ui]；reject 同理。
767	async function decideFromCli({ root, positionals, flags }, decision) {
768	  const name = decision === 'approved' ? 'approve' : 'reject';
769	  const id = positionals[0] ?? (typeof flags.id === 'string' ? flags.id : undefined);
770	  if (!id) {
771	    throw new CliError(`${name} 需要请示编号，例如：${name} A-0001`);
772	  }
773	  if (flags.note === true) {
774	    throw new CliError('--note 需要带批注内容');
775	  }
776	  if (flags.via === true) {
777	    throw new CliError('--via 需要注明入口（cli 或 ui）');
778	  }
779	  const note = typeof flags.note === 'string' ? flags.note : null;
780	  const via = typeof flags.via === 'string' && flags.via.trim() !== '' ? flags.via : 'cli';
781	  const result = await decide(root, id, { decision, via, note });
782	  return { output: { ok: true, ...result }, exit: EXIT.OK };
783	}
784	
785	async function cmdApprove(ctx) {
786	  return decideFromCli(ctx, 'approved');
787	}
788	
789	async function cmdReject(ctx) {
790	  return decideFromCli(ctx, 'rejected');
791	}
792	
793	// report-issue 子命令：老板随手评——对某件产出（artifact）主动报一个问题。
794	// 用法：report-issue --artifact <产出id> --note "哪里不对、期望怎样"
795	// 只落一条 report:true 的 artifact-review 自留档（活锁放行、不碰在跑 tick 的业务档）；真正的
796	// 重开返修由下一轮 precheck(reopen-for-report)+fire 干。里程碑从该产出的 source=milestone/<id> 推出：
797	// 只对「里程碑主产出」报得了问题（非里程碑产出没有可返修的归属，白话拒收）。
798	async function cmdReportIssue({ root, flags }) {
799	  const artifactId = typeof flags.artifact === 'string' && flags.artifact.trim() !== '' ? flags.artifact.trim() : undefined;
800	  if (!artifactId) {
801	    throw new CliError('report-issue 需要 --artifact 带上产出 id，例如：report-issue --artifact a-1a2b3c4d --note "首页按钮点了没反应"');
802	  }
803	  if (flags.note === true || typeof flags.note !== 'string' || flags.note.trim() === '') {
804	    throw new CliError('report-issue 需要 --note 写清楚问题：哪里不对、期望怎样，下一轮 agent 照它返修');
805	  }
806	  const artifacts = await listArtifacts(root);
807	  const artifact = artifacts.find((a) => a.id === artifactId);
808	  if (!artifact) {
809	    throw new CliError(`产出「${artifactId}」不在画廊里，报不了问题（可能已被清理或 id 不对）`);
810	  }
811	  const source = typeof artifact.source === 'string' ? artifact.source : '';
812	  const milestone = source.startsWith('milestone/') ? source.slice('milestone/'.length) : '';
813	  if (milestone === '') {
814	    throw new CliError(`产出「${artifactId}」不是某个里程碑的主产出（source 不是 milestone/<编号>），没有可返修的归属，报不了问题`);
815	  }
816	  const state = await readJson(root, PATHS.state);
817	  const tick = state !== null && Number.isInteger(state.tick_seq) ? state.tick_seq : 0;
818	  const result = await fileIssueReport(root, { artifactId, milestone, note: flags.note, tick });
819	  return { output: { ok: true, ...result, milestone, artifact_id: artifactId }, exit: EXIT.OK };
820	}
821	
822	// mark-polished 子命令：老板「准入+意见」里的那条打磨意见已经做完了，回填标记。
823	// 用法：mark-polished --id <准入单编号> --gen n（有锁在手时写类子命令必须报代数）

