export async function runAcceptance(root, milestoneId, { actor = '脚本' } = {}) {
  const milestones = await readJson(root, MILESTONES_REL);
  if (!Array.isArray(milestones)) {
    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法验收`);
  }
  const entry = milestones.find((m) => m.id === milestoneId);
  if (!entry) {
    throw new Error(`里程碑清单里找不到「${milestoneId}」，没法验收`);
  }
  const status = entry.status ?? 'planned'; // 没写过状态的里程碑就是刚排期的
  if (status === 'done' || status === 'voided') {
    throw new Error(`里程碑「${milestoneId}」已经是「${status}」，终态不再验收`);
  }
  // 验收只发生在「团队自称完成」与「老板验收」之间：没申报就没得验。
  if (!Number.isInteger(entry.claimed_at_tick)) {
    throw new Error(`里程碑「${milestoneId}」还没申报完成（缺 claimed_at_tick），先经 write milestone-claim 申报再验收`);
  }

  // —— 评判段：纯读，一个字都不写。——
  const failed = [];
  const checked = [];
  const needsInspector = [];
  for (const [i, criterion] of entry.criteria.entries()) {
    const where = `里程碑 ${milestoneId} 第 ${i + 1} 条验收标准`;
    if (criterion.manual === true) {
      needsInspector.push({ index: i, desc: criterion.desc });
      continue;
    }
    const { ok, reason } = await judgeCheck(root, criterion.check, where);
    checked.push({ index: i, desc: criterion.desc, ok, ...(ok ? {} : { reason }) });
    if (!ok) failed.push({ index: i, desc: criterion.desc, reason });
  }

  // 程序判的全过、但有人判条目没回填：不定案。检察会话回填 verdict 之前，状态原地不动。
  if (failed.length === 0 && needsInspector.length > 0) {
    return { pass: null, failed: [], needs_inspector: needsInspector, incident: false };
  }

  // —— 评审门（review_required）——
  // 机器标准全过、也没有待 AI 检察的人判条目，但这个里程碑定义了「要老板亲自评审」：不由脚本径直定 done，
  // 改挂/认一张 artifact-review 评审单，按老板的准入/打回定案。与 needs_inspector（AI 检察员）彻底分家——
  // 这里返回独立的 awaiting_review 信号（pass 仍是 null 但 needs_inspector 为空），fire/剧本据此暂停等老板、
  // 绝不拉 AI 检察员。approved→落到下面的 pass 回路推 done（advance 硬闸此时放行）；rejected→把打回意见
  // 转成一条失败项，落到下面的 failed 回路（里程碑 failed+needs_fix，precheck 下轮当 defect 直奔去修）。
  // 两种里程碑要过评审门：定义时声明 review_required 的；以及被老板报过问题、这一轮修完需复审的
  //（review_after_fix，老板规则：打回/报问题＝我要再看，准入+意见＝别烦我）。
  let approvedReviewId = null; // 凭哪张单放行的；推完 done 再盖消费戳（盖早了硬闸会把自己拦下）
  if (failed.length === 0 && (entry.review_required === true || entry.review_after_fix === true)) {
    const review = await findArtifactReviewForClaim(root, milestoneId, entry.claimed_at_tick);
    if (review === null || (review.status ?? 'pending') === 'pending') {
      // 送验收（planned/failed→verifying），让里程碑在评审期间显示「验收中/待评审」；已在 verifying 不重复推。
      if (status !== 'verifying') {
        await advance(root, 'milestone', milestoneId, 'verifying', { actor });
      }
      let approvalId;
      let artifactId;
      if (review === null) {
        // 头一回走到评审门：挂一张评审单，绑本里程碑的主产出（source=milestone/<编号>）。
        const requiredSource = `milestone/${milestoneId}`;
        const artifact = (await listArtifacts(root)).find((a) => a.source === requiredSource);
        if (artifact === undefined) {
          // review_required 蕴含 artifact_required、claim 闸已保证主产出在册；查无＝档案对不上，喊停不猜。
          throw new Error(
            `里程碑「${milestoneId}」要评审却找不到主产出（画廊里没有 source=${requiredSource} 的 artifact），` +
              '档案对不上（review_required 本应蕴含 artifact_required + claim 闸兜底），停手等人查'
          );
        }
        const filed = await fileApproval(root, {
          type: 'artifact-review',
          kind: 'artifact-review',
          title: `请老板试用并评审产出：${typeof artifact.title === 'string' ? artifact.title : milestoneId}`,
          artifactId: artifact.id,
          milestone: milestoneId,
          requestedBy: actor,
          tick: entry.claimed_at_tick
        });
        approvalId = filed.id;
        artifactId = artifact.id;
      } else {
        // 已挂单、老板还没拍板：原地继续等（幂等，绝不重复挂单）。
        approvalId = review.id;
        artifactId = review.artifact_id;
      }
      return {
        pass: null,
        failed: [],
        needs_inspector: [],
        awaiting_review: { approval: approvalId, artifact_id: artifactId, milestone: milestoneId },
        incident: false
      };
    }
    if ((review.status ?? 'pending') === 'rejected') {
      // 老板打回：把打回意见转成一条失败项，走下面的 failed 回路。
      const note = review.decision?.note;
      failed.push({
        index: -1,
        desc: `老板评审打回产出（评审单 ${review.id}）`,
        reason: typeof note === 'string' && note.trim() !== '' ? note.trim() : '（老板未留具体意见）'
      });
    }

